// Records and the runtime-neutral Storage interface (ARCHITECTURE §4, ADR-0006). Times are epoch milliseconds, ids are
// generated by the caller, lists and objects are JSON. The storage layer never sees a plaintext Agility token.

export type JsonValue = null | boolean | number | string | JsonValue[] | { [key: string]: JsonValue };
export type JsonObject = { [key: string]: JsonValue };

export type Role = 'owner' | 'admin' | 'member';
export type ValidationStatus = 'unvalidated' | 'valid' | 'invalid';
/** `stored`: grants use stored credentials; `passthrough`: callers send their own Agility token (P2-14). */
export type CredentialSource = 'stored' | 'passthrough';
export type AuditKind = 'tool_call' | 'write' | 'auth' | 'admin';
export type AuditStatus = 'ok' | 'error' | 'denied';

export interface User {
  id: string;
  /** Lower case, unique. */
  email: string;
  displayName: string | null;
  /** Identity provider and its subject, unique together; both set or both null. */
  idp: string | null;
  idpSubject: string | null;
  role: Role;
  createdAt: number;
  updatedAt: number;
  disabledAt: number | null;
}

export interface Instance {
  id: string;
  label: string;
  /** Canonical base URL (core `canonicalInstanceUrl`), unique. */
  baseUrl: string;
  /** TLS options (a CA bundle reference; Node only). */
  tls: JsonObject | null;
  /** Asset-number prefix overrides. */
  numberPrefixes: JsonObject | null;
  metaFingerprint: string | null;
  createdAt: number;
  updatedAt: number;
  disabledAt: number | null;
}

export interface Credential {
  id: string;
  instanceId: string;
  /** `null` = a shared credential owned by the deployment. */
  ownerUserId: string | null;
  label: string;
  /** AES-256-GCM ciphertext and IV, base64url (ADR-0007, P2-03). */
  tokenCiphertext: string;
  tokenIv: string;
  keyVersion: number;
  /** At most the last 4 characters of the token. */
  tokenHint: string;
  validationStatus: ValidationStatus;
  validationErrorCode: string | null;
  validatedAt: number | null;
  memberOid: string | null;
  memberName: string | null;
  memberUsername: string | null;
  reachableScopeIds: string[] | null;
  createdAt: number;
  updatedAt: number;
  revokedAt: number | null;
}

export interface Workspace {
  id: string;
  /** URL segment of `/w/{slug}/mcp`, unique. */
  slug: string;
  name: string;
  instanceId: string;
  allowedScopeIds: string[];
  includeChildScopes: boolean;
  /** Asset-type policy; `null` = every type the instance allows (refined by P2-04). */
  assetTypes: JsonObject | null;
  /** `null` = every read tool. */
  enabledTools: string[] | null;
  limits: JsonObject;
  /** A shared credential of the same instance. */
  defaultCredentialId: string | null;
  writePolicy: JsonObject;
  credentialSource: CredentialSource;
  createdAt: number;
  updatedAt: number;
  disabledAt: number | null;
}

export interface Grant {
  id: string;
  workspaceId: string;
  /** `null` = a service grant, which needs a label. */
  userId: string | null;
  label: string | null;
  /** `null` = the workspace's default credential. Otherwise a credential of the workspace's instance that is shared or
   * owned by `userId`. */
  credentialId: string | null;
  /** `null` = no narrowing on that dimension. */
  tools: string[] | null;
  scopeIds: string[] | null;
  assetTypes: JsonObject | null;
  limits: JsonObject;
  rateLimit: JsonObject | null;
  createdAt: number;
  updatedAt: number;
  expiresAt: number | null;
  revokedAt: number | null;
}

export interface AccessToken {
  id: string;
  grantId: string;
  /** Display prefix: `ab_live_` or `ab_test_` and the first 4 characters of the token (P2-05). */
  prefix: string;
  /** SHA-256 of the token, lower-case hex, unique. */
  tokenHash: string;
  /** The device. */
  label: string;
  createdAt: number;
  expiresAt: number | null;
  lastUsedAt: number | null;
  revokedAt: number | null;
}

export interface AuditEntry {
  id: string;
  ts: number;
  kind: AuditKind;
  action: string;
  status: AuditStatus;
  requestId: string | null;
  userId: string | null;
  grantId: string | null;
  tokenId: string | null;
  clientId: string | null;
  workspaceId: string | null;
  instanceId: string | null;
  assetNumbers: string[] | null;
  /** The compiled query with every bound value masked. */
  query: string | null;
  durationMs: number | null;
  agilityRequests: number | null;
  errorCode: string | null;
  targetType: string | null;
  targetId: string | null;
  details: JsonObject | null;
}

export interface Setting {
  key: string;
  value: JsonValue;
  updatedAt: number;
}

/** Fields the caller supplies on create; `createdAt`/`updatedAt` come from the storage clock. */
type NewRecord<T, Required extends keyof T> = Pick<T, Required> &
  Partial<Omit<T, Required | 'createdAt' | 'updatedAt'>>;

export type NewUser = NewRecord<User, 'id' | 'email' | 'role'>;
export type NewInstance = NewRecord<Instance, 'id' | 'label' | 'baseUrl'>;
export type NewCredential = NewRecord<
  Credential,
  'id' | 'instanceId' | 'label' | 'tokenCiphertext' | 'tokenIv' | 'keyVersion' | 'tokenHint'
>;
export type NewWorkspace = NewRecord<Workspace, 'id' | 'slug' | 'name' | 'instanceId'>;
export type NewGrant = NewRecord<Grant, 'id' | 'workspaceId'>;
export type NewAccessToken = NewRecord<AccessToken, 'id' | 'grantId' | 'prefix' | 'tokenHash' | 'label'>;
export type NewAuditEntry = Pick<AuditEntry, 'id' | 'ts' | 'kind' | 'action' | 'status'> &
  Partial<Omit<AuditEntry, 'id' | 'ts' | 'kind' | 'action' | 'status'>>;

/** Columns that never change after creation are not patchable (identity, ownership, parent, secret material). */
export type UserPatch = Partial<
  Pick<User, 'email' | 'displayName' | 'idp' | 'idpSubject' | 'role' | 'disabledAt'>
>;
export type InstancePatch = Partial<
  Pick<Instance, 'label' | 'baseUrl' | 'tls' | 'numberPrefixes' | 'metaFingerprint' | 'disabledAt'>
>;
export type CredentialPatch = Partial<
  Pick<
    Credential,
    | 'label'
    | 'tokenHint'
    | 'validationStatus'
    | 'validationErrorCode'
    | 'validatedAt'
    | 'memberOid'
    | 'memberName'
    | 'memberUsername'
    | 'reachableScopeIds'
    | 'revokedAt'
  >
>;
export type WorkspacePatch = Partial<
  Pick<
    Workspace,
    | 'slug'
    | 'name'
    | 'allowedScopeIds'
    | 'includeChildScopes'
    | 'assetTypes'
    | 'enabledTools'
    | 'limits'
    | 'defaultCredentialId'
    | 'writePolicy'
    | 'credentialSource'
    | 'disabledAt'
  >
>;
export type GrantPatch = Partial<
  Pick<
    Grant,
    | 'label'
    | 'credentialId'
    | 'tools'
    | 'scopeIds'
    | 'assetTypes'
    | 'limits'
    | 'rateLimit'
    | 'expiresAt'
    | 'revokedAt'
  >
>;
export type AccessTokenPatch = Partial<Pick<AccessToken, 'label' | 'expiresAt' | 'revokedAt'>>;

export interface Repository<T, New, Patch> {
  /** The row, or `null` when it does not exist. */
  get(id: string): Promise<T | null>;
  /** Inserts a row. `ConflictError` on a duplicate id or unique value, `InvalidInputError` on a rule violation. */
  create(record: New): Promise<T>;
  /** Updates the given columns and `updatedAt`. `NotFoundError` when the row does not exist. */
  update(id: string, patch: Patch): Promise<T>;
  /** Deletes a row (cascades and restrictions of ARCHITECTURE §4). `NotFoundError` when it does not exist,
   * `ConflictError` when other rows still reference it. */
  delete(id: string): Promise<void>;
}

export interface UserRepository extends Repository<User, NewUser, UserPatch> {
  getByEmail(email: string): Promise<User | null>;
  getByIdentity(idp: string, idpSubject: string): Promise<User | null>;
  list(): Promise<User[]>;
}

export interface InstanceRepository extends Repository<Instance, NewInstance, InstancePatch> {
  list(): Promise<Instance[]>;
}

/** The encrypted token of a credential (ADR-0007). */
export type SealedToken = Pick<Credential, 'tokenCiphertext' | 'tokenIv' | 'keyVersion'>;

export interface CredentialRepository extends Repository<Credential, NewCredential, CredentialPatch> {
  /** `ownerUserId: null` lists shared credentials only. */
  list(filter?: {
    instanceId?: string;
    ownerUserId?: string | null;
    keyVersion?: number;
  }): Promise<Credential[]>;
  /**
   * Replaces the encrypted token only while the row still holds `expected` (compare-and-swap, for key rotation and
   * token replacement); `true` when it wrote. `updatedAt` is not changed by a re-encryption.
   */
  replaceSecret(id: string, expected: SealedToken, next: SealedToken): Promise<boolean>;
}

export interface WorkspaceRepository extends Repository<Workspace, NewWorkspace, WorkspacePatch> {
  getBySlug(slug: string): Promise<Workspace | null>;
  list(filter?: { instanceId?: string }): Promise<Workspace[]>;
}

export interface GrantRepository extends Repository<Grant, NewGrant, GrantPatch> {
  list(filter?: { workspaceId?: string; userId?: string; credentialId?: string }): Promise<Grant[]>;
}

/** Everything access resolution reads for one device token; missing rows are `null` (the resolver denies). */
export interface AccessBundle {
  readonly token: AccessToken | null;
  readonly grant: Grant | null;
  readonly workspace: Workspace | null;
  readonly user: User | null;
  readonly instance: Instance | null;
  /** The grant's credential, or the workspace default when the grant names none. */
  readonly credential: Credential | null;
}

export interface AccessTokenRepository extends Repository<AccessToken, NewAccessToken, AccessTokenPatch> {
  getByHash(tokenHash: string): Promise<AccessToken | null>;
  /** The token by hash and every record its access depends on, in one round trip on SQL (one `batch()`, P3-02). */
  bundleByHash(tokenHash: string): Promise<AccessBundle>;
  list(filter?: { grantId?: string }): Promise<AccessToken[]>;
  /** Sets `lastUsedAt` to now unless it was set less than `minIntervalMs` ago; `true` when it wrote. */
  touch(id: string, minIntervalMs: number): Promise<boolean>;
}

export interface AuditQuery {
  workspaceId?: string;
  userId?: string;
  kind?: AuditKind;
  status?: AuditStatus;
  /** Inclusive lower and exclusive upper bound on `ts`. */
  from?: number;
  to?: number;
  /** Newest first; continue after the last row of the previous page. */
  after?: { ts: number; id: string };
  /** Default 100, at most 1,000. */
  limit?: number;
}

/** Append-only: rows are never updated, and deleted only by retention (THREAT_MODEL T17). */
export interface AuditRepository {
  append(entry: NewAuditEntry): Promise<void>;
  query(query?: AuditQuery): Promise<AuditEntry[]>;
  /** Deletes rows with `ts` before `before`, at most `limit` (default 1,000) per call; returns how many. */
  purge(before: number, limit?: number): Promise<number>;
}

export interface SettingsRepository {
  get(key: string): Promise<Setting | null>;
  set(key: string, value: JsonValue): Promise<Setting>;
  delete(key: string): Promise<boolean>;
  list(): Promise<Setting[]>;
}

export interface KvSetOptions {
  /** Absolute expiry (epoch ms). Expired entries read as absent. */
  expiresAt?: number | null;
}

export interface KvIncrementOptions {
  by?: number;
  /** Expiry of a new (or expired, hence restarted) counter; an existing counter keeps its expiry. */
  expiresAt?: number | null;
  /** The counter never exceeds this: an increment that would is refused and returns `null`. */
  max?: number;
}

/** Short-lived state: single-use markers, OAuth provider records, counters (ADR-0006). Values are opaque strings. */
export interface KvStore {
  get(key: string): Promise<string | null>;
  set(key: string, value: string, options?: KvSetOptions): Promise<void>;
  /** Stores only when the key is absent or expired; `true` when it stored. */
  setIfAbsent(key: string, value: string, options?: KvSetOptions): Promise<boolean>;
  /** Removes and returns a live value in one step: of concurrent callers, exactly one gets it (L-073). */
  take(key: string): Promise<string | null>;
  delete(key: string): Promise<boolean>;
  /** Atomically adds `by` (default 1) and returns the new value, or `null` when `max` would be exceeded. */
  increment(key: string, options?: KvIncrementOptions): Promise<number | null>;
  /** Live keys with this prefix, in key order, after `after`, at most `limit` (default 100, at most 1,000). */
  list(prefix: string, options?: { after?: string; limit?: number }): Promise<string[]>;
  /** Deletes expired entries, at most `limit` (default 1,000) per call; returns how many. */
  purgeExpired(limit?: number): Promise<number>;
}

export interface Storage {
  readonly readOnly: boolean;
  readonly users: UserRepository;
  readonly instances: InstanceRepository;
  readonly credentials: CredentialRepository;
  readonly workspaces: WorkspaceRepository;
  readonly grants: GrantRepository;
  readonly accessTokens: AccessTokenRepository;
  readonly audit: AuditRepository;
  readonly settings: SettingsRepository;
  readonly kv: KvStore;
  close(): Promise<void>;
}

/** Epoch milliseconds; injected so tests control expiry. */
export type Now = () => number;
